  conditions_intro text not null,
  conditions jsonb not null default '[]'::jsonb,
  sections jsonb not null default '[]'::jsonb,
  patient_story jsonb not null,
  faqs jsonb not null default '[]'::jsonb,
  final_cta text not null,
  disclaimer text not null,
  disclaimer_prominent boolean not null default false,
  about_condition jsonb not null,
  is_published boolean not null default true,
  display_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.disease_pages enable row level security;

-- Anyone (anon key, used by the website) can read published pages only.
create policy "Public can read published disease pages"
